Rules.InvariantScript:
// A stale global error from another screen must not appear here.
Set(gblError, {IsVisible: false, Title: "", Detail: ""});

// Filter option lists. Each carries an "all" row whose Code is blank.
// Dropdowns are fed a SINGLE-COLUMN table (Label only) so there is no ambiguity
// about which column displays; the code is mapped back with LookUp.
ClearCollect(colFDomain, {Code: "", Label: "All domains"});
Collect(colFDomain, ShowColumns(gblDomains, "Code", "Label"));

// The queue filters on StatusGroup: OPEN | RESOLVED | SUPPRESSED | ALL.
// Confirmed from the procedure body and from the dq.Lookup 'StatusGroup' set.
ClearCollect(colFStatus, ShowColumns(colLkStatusGroup, "Code", "Label"));

ClearCollect(colFSeverity, {Code: "", Label: "All severities"});
Collect(colFSeverity, ShowColumns(colLkSeverity, "Code", "Label"));

ClearCollect(colFSource, {Code: "", Label: "All sources"});
Collect(colFSource, ShowColumns(colLkSource, "Code", "Label"));

// The procedure translates the literal 'me' to the actor. There is NO
// unassigned filter - usp_GetExceptionQueue only supports
// "@AssigneeUpn IS NULL OR AssignedToUpn = @AssigneeUpn" - so that option
// is deliberately absent rather than offered and silently returning nothing.
ClearCollect(
    colFAssignee,
    {Code: "", Label: "Anyone"},
    {Code: "me", Label: "Me"}
);

UpdateContext(
    {
        locDomain: "",
        locStatus: "OPEN",
        locSeverity: Coalesce(locInSeverity, ""),
        locSource: "",
        locAssignee: Coalesce(locInAssignee, ""),
        locOverdue: Coalesce(locInOverdue, false),
        locSearch: "",
        locClusterId: locInCluster,
        locPage: 1,
        locBulkOpen: false,
        locBulkStatus: ""
    }
);
Select(btnDoLoadQueue)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    ClearCollect(
        colQueue,
        Filter(
        db_dq_sandbox.dquspGetExceptionQueue(
            {
                ActorUpn: gblActorUpn,
                DomainCode: If(locDomain = "", Blank(), locDomain),
                StatusGroup: locStatus,
                SeverityCode: If(locSeverity = "", Blank(), locSeverity),
                SourceSystem: If(locSource = "", Blank(), locSource),
                AssigneeUpn: If(locAssignee = "", Blank(), locAssignee),
                OverdueOnly: locOverdue,
                SearchText: Trim(locSearch),
                ClusterId: locClusterId,
                Page: locPage,
                PageSize: Coalesce(gblCfg.PageSize, 50),
                SortColumn: "AgeDays",
                SortDirection: "DESC"
            }
        ).ResultSets.Table1,
            !IsBlank(ExceptionId)
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not load the queue", Detail: FirstError.Message})
);
UpdateContext({locTotal: Coalesce(First(colQueue).TotalCount, 0)});
Clear(colQueueSelected);
Set(gblBusy, false)

Reset(txtSearchQU);
UpdateContext(
    {
        locDomain: "",
        locStatus: "OPEN",
        locSeverity: "",
        locSource: "",
        locAssignee: "",
        locOverdue: false,
        locSearch: "",
        locClusterId: Blank(),
        locPage: 1
    }
);
Select(btnDoLoadQueue)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblBulkResult,
        db_dq_sandbox.dquspBulkDisposition(
            {
                ActorUpn: gblActorUpn,
                ExceptionIdCsv: Concat(colQueueSelected, Text(ExceptionId), ","),
                ToStatusCode: locBulkStatus,
                Reason: Trim(txtBulkReasonQU.Text)
            }
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Bulk disposition failed", Detail: FirstError.Message})
);
ClearCollect(colBulkFailures, gblBulkResult.ResultSets.Table2);
UpdateContext({locBulkOpen: false});
Notify(
    Text(Coalesce(First(gblBulkResult.ResultSets.Table1).SucceededCount, 0)) & " updated, " &
    Text(Coalesce(First(gblBulkResult.ResultSets.Table1).FailedCount, 0)) & " failed.",
    If(
        Coalesce(First(gblBulkResult.ResultSets.Table1).FailedCount, 0) > 0,
        NotificationType.Warning,
        NotificationType.Success
    ),
    6000
);
Set(gblBusy, false);
Select(btnDoLoadQueue)
